void eegDummyGenerate16(float *ch)
{
    for (int i = 0; i < 16; i++) {
        ch[i] = pgm_read_float(&dataset[currentIndex][i]);
    }

    currentIndex++;
    if (currentIndex >= TOTAL_SAMPLES)
        currentIndex = 0;
}
void eegDummyReset(void)
{
    currentIndex = 0;
}